<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Auto‑Snake</title>
<style>
  body { margin:0; background:#111; color:#0f0; font-family:sans-serif; overflow:hidden; }
  #score { position:absolute; top:10px; left:10px; font-size:24px; }
  canvas { display:block; margin:auto; background:#111; }
</style>
</head>
<body>
<div id="score">Score: 0</div>
<canvas id="game" width="600" height="600"></canvas>
<script>
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const gridSize = 20;
  const cols = canvas.width / gridSize;
  const rows = canvas.height / gridSize;

  let snake = [{x: Math.floor(cols/2), y: Math.floor(rows/2)}];
  let food = randomFood();
  let dx = 0, dy = 0; // current velocity
  let score = 0;
  const speed = 100; // ms per move

  function randomFood() {
    let pos;
    do {
      pos = {x: Math.floor(Math.random()*cols), y: Math.floor(Math.random()*rows)};
    } while (snake.some(s=>s.x===pos.x && s.y===pos.y));
    return pos;
  }

  function updateDirection() {
    const head = snake[0];
    // Simple greedy AI: move horizontally first, then vertically
    if (head.x < food.x) { dx = 1; dy = 0; }
    else if (head.x > food.x) { dx = -1; dy = 0; }
    else if (head.y < food.y) { dx = 0; dy = 1; }
    else if (head.y > food.y) { dx = 0; dy = -1; }
    else { dx = dy = 0; } // already on food
  }

  function step() {
    updateDirection();

    const newHead = {x: snake[0].x + dx, y: snake[0].y + dy};

    // Wall collision → reset game
    if (newHead.x < 0 || newHead.x >= cols || newHead.y < 0 || newHead.y >= rows) {
      reset();
      return;
    }

    // Self collision → reset game
    if (snake.some(s => s.x === newHead.x && s.y === newHead.y)) {
      reset();
      return;
    }

    snake.unshift(newHead);

    // Eat food?
    if (newHead.x === food.x && newHead.y === food.y) {
      score++;
      document.getElementById('score').textContent = 'Score: ' + score;
      food = randomFood();
    } else {
      snake.pop(); // move without growing
    }

    draw();
  }

  function draw() {
    ctx.clearRect(0,0,canvas.width,canvas.height);
    // Draw food
    ctx.fillStyle = 'red';
    ctx.fillRect(food.x*gridSize, food.y*gridSize, gridSize, gridSize);
    // Draw snake
    ctx.fillStyle = '#0f0';
    snake.forEach(seg => {
      ctx.fillRect(seg.x*gridSize, seg.y*gridSize, gridSize, gridSize);
    });
  }

  function reset() {
    snake = [{x: Math.floor(cols/2), y: Math.floor(rows/2)}];
    food = randomFood();
    dx = dy = 0;
    score = 0;
    document.getElementById('score').textContent = 'Score: 0';
  }

  setInterval(step, speed);
})();
</script>
</body>
</html>
```
The script repeatedly compares the snake’s head coordinates to the food’s coordinates, sets the movement direction toward the food, and updates/render the game automatically.
